// ─── JSValue 核心类型（补全）──────────────────────────────────────────────
// C 侧定义（quickjs.h）：
//   typedef union { int32_t int32; double float64; void* ptr; int64_t short_big_int; } JSValueUnion;
//   typedef struct { JSValueUnion u; int64_t tag; } JSValue;
// union 是 8 字节，tag 是 8 字节，总计 16 字节。
// V 侧用 u64 占位 union，ABI 完全等价；字段访问用下方辅助函数。
@[typedef]
pub struct C.JSValue {
pub mut:
	u   u64
	tag i64
}

// 兼容别名
pub type JSValue = C.JSValue

// 辅助：union 字段的各种 reinterpret 访问。
@[inline]
pub fn (v JSValue) get_tag() i64 {
	return v.tag
}

@[inline]
pub fn (v JSValue) get_i32() i32 {
	return i32(v.u & 0xFFFF_FFFF)
}

@[inline]
pub fn (v JSValue) get_bool() bool {
	return (v.u & 0xFFFF_FFFF) != 0
}

@[inline]
pub fn (v JSValue) get_f64() f64 {
	mut out := f64(0)
	unsafe {
		vmemcpy(&out, &v.u, sizeof(f64))
	}
	return out
}

@[inline]
pub fn (v JSValue) get_ptr() voidptr {
	return voidptr(v.u)
}

@[inline]
pub fn (v JSValue) get_int64() i64 {
	return i64(v.u)
}

// 构造：mk_val(tag, u64 payload)
@[inline]
pub fn mk_val(tag i64, payload u64) JSValue {
	return JSValue{
		u:   payload
		tag: tag
	}
}

