// ─── 宏 JS_VALUE_IS_NAN（V inline 实现，宏无符号可链接）──────────────────
// 原宏： #define JS_VALUE_IS_NAN(v) isnan(JS_VALUE_GET_FLOAT64(v))
@[inline]
pub fn js_value_is_nan(v JSValue) bool {
	if v.tag != tag_float64 {
		return false
	}
	return math.is_nan(v.get_f64())
}

